script:
try {
  $r = Invoke-WebRequest -Uri "http://100.107.85.14:8472/api/flagged" -TimeoutSec 5 -UseBasicParsing | ConvertFrom-Json
  "dashboard UP — flagged: $($r.total), reviewed: $($r.reviewed)"
  $h = Invoke-WebRequest -Uri "http://100.107.85.14:8472/" -TimeoutSec 5 -UseBasicParsing
  if ($h.Content -like "*video-section*") { "HTML has collapsible sections" } else { "HTML MISSING new code" }
} catch {
  "DASHBOARD DOWN: " + $_.Exception.Message
}
